52: // Admission metadata, not claim semantics. This set says only that a claim
53: // cannot be admitted through the generic path without a contextual validator.
54: // It is never consulted by assessEdge, evaluateAssurance or Policy.
55: const CONTEXT_REQUIRED_CLAIMS: ReadonlySet<string> = new Set(['PARENT_UNRESOLVED']);
